description:
Write a small "options" pattern that the C standard library would call idiomatic today:

```c
struct export_options
{
    const char *separator;   /* default "," */
    int header;              /* default 1 (print a header line) */
    int precision;           /* default 2 */
};

/* Fills in every field still at its zero value with its default. */
struct export_options with_defaults(struct export_options o);

/* Writes "name<sep>value\n" per row into out (at most size bytes, always zero-terminated),
   with a "name<sep>value\n" header first when header is set. Values use the precision.
   Returns the number of characters the full text needs, like snprintf. */
int export_rows(char *out, size_t size, const char *const *names, const double *values, int count,
                struct export_options o);

#define EXPORT(out, size, names, values, count, ...) \
    export_rows((out), (size), (names), (values), (count), with_defaults((struct export_options){ __VA_ARGS__ }))
```

so that callers can write `EXPORT(buf, sizeof buf, names, values, 2, .precision = 3)` or `EXPORT(buf, sizeof buf, names, values, 2, .separator = ";", .header = -1)`, naming only the options they change. (Strict C17 wants at least one option after the count; pass `.separator = ","` to take every default.)

Because 0 means "use the default", a caller who wants no header passes `.header = -1`, and `with_defaults` turns `-1` into 0; for precision, `-1` means 0 decimals.

starter.solution.c:
#include <stdio.h>

struct export_options
{
    const char *separator;
    int header;
    int precision;
};

struct export_options with_defaults(struct export_options o)
{
    return o;
}

int export_rows(char *out, size_t size, const char *const *names, const double *values, int count,
                struct export_options o)
{
    if (size > 0) out[0] = '\0';
    return 0;
}

#define EXPORT(out, size, names, values, count, ...) \
    export_rows((out), (size), (names), (values), (count), with_defaults((struct export_options){ __VA_ARGS__ }))

solution.solution.c:
#include <stdio.h>

struct export_options
{
    const char *separator;
    int header;
    int precision;
};

struct export_options with_defaults(struct export_options o)
{
    if (o.separator == NULL) o.separator = ",";
    if (o.header == 0) o.header = 1;
    else if (o.header < 0) o.header = 0;
    if (o.precision == 0) o.precision = 2;
    else if (o.precision < 0) o.precision = 0;
    return o;
}

int export_rows(char *out, size_t size, const char *const *names, const double *values, int count,
                struct export_options o)
{
    int total = 0;
    if (size > 0) out[0] = '\0';
    if (o.header)
    {
        int n = snprintf(out, size, "name%svalue\n", o.separator);
        if (n < 0) return n;
        total += n;
    }
    for (int i = 0; i < count; i++)
    {
        size_t used = (size_t)total < size ? (size_t)total : size;
        int n = snprintf(size > used ? out + used : NULL, size > used ? size - used : 0,
                         "%s%s%.*f\n", names[i], o.separator, o.precision, values[i]);
        if (n < 0) return n;
        total += n;
    }
    return total;
}

#define EXPORT(out, size, names, values, count, ...) \
    export_rows((out), (size), (names), (values), (count), with_defaults((struct export_options){ __VA_ARGS__ }))

unitTests:
TEST("defaults") { struct export_options o = with_defaults((struct export_options){ 0 }); CHECK_STR(o.separator, ","); CHECK_EQ(o.header, 1); CHECK_EQ(o.precision, 2); o = with_defaults((struct export_options){ .header = -1, .precision = -1 }); CHECK_EQ(o.header, 0); CHECK_EQ(o.precision, 0); }
TEST("exporting") { const char *names[] = { "pi", "e" }; double values[] = { 3.14159, 2.71828 }; char buf[100]; int n = export_rows(buf, sizeof buf, names, values, 2, with_defaults((struct export_options){ 0 })); CHECK_STR(buf, "name,value
pi,3.14
e,2.72
"); CHECK_EQ(n, 26); export_rows(buf, sizeof buf, names, values, 2, with_defaults((struct export_options){ .separator = ";", .precision = -1, .header = -1 })); CHECK_STR(buf, "pi;3
e;3
"); }
TEST("a small buffer is cut but measured") { const char *names[] = { "alpha", "beta" }; double values[] = { 1, 2 }; char small[10]; int n = export_rows(small, sizeof small, names, values, 2, with_defaults((struct export_options){ .header = -1 })); CHECK_STR(small, "alpha,1.0"); CHECK_EQ(n, 21); }

